package com.tapeverify.copilot.controller;
import com.tapeverify.copilot.dto.BatchSummaryDto; import com.tapeverify.copilot.service.IngestionService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/loans") public class IngestionController { private final IngestionService service; public IngestionController(IngestionService service){this.service=service;} @PostMapping(value="/ingest",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ResponseEntity<BatchSummaryDto> ingest(@RequestPart("file") MultipartFile file,@RequestParam(defaultValue="PRIMARY") String sourceType){return ResponseEntity.status(HttpStatus.CREATED).body(service.ingest(file,sourceType));} }
